/**
 * Step 2: Safe, Idempotent Multi-Company Migration Script
 *
 * Defaults to DRY-RUN mode. Requires an explicit `--apply` flag AND a verified
 * `--backup-manifest <path>` generated by backupFirestore.ts before modifying Firestore.
 *
 * Actions:
 * 1. Creates LUMERE GROUP (parent) and subsidiaries LUMERE, NEX AURA, ORDARK.
 * 2. Seeds suggested departments for NEX AURA and ORDARK (without duplicating).
 * 3. Assigns all existing users/departments/clients/projects/tasks/comments/notifications/
 *    activity_logs/equipment/equipmentHistory to valid companyId without deleting any fields.
 *
 * Usage:
 *   Dry-run:
 *     npx tsx scripts/migration/migrateToMultiCompany.ts --dry-run
 *   Apply:
 *     npx tsx scripts/migration/migrateToMultiCompany.ts --apply --backup-manifest backups/firestore-.../manifest.json
 */

import fs from 'node:fs';
import { initializeApp, cert, applicationDefault } from 'firebase-admin/app';
import { getFirestore } from 'firebase-admin/firestore';
import {
  buildFullMigrationPlan,
  COMPANY_OWNED_COLLECTIONS,
  RawDocument,
} from './lib/migrationLogic';

const DEFAULT_PROJECT_ID = 'lumere-erb';

function parseArgs() {
  const args = process.argv.slice(2);
  const apply = args.includes('--apply');
  const manifestIdx = args.indexOf('--backup-manifest');
  const backupManifestPath = manifestIdx >= 0 ? args[manifestIdx + 1] : null;
  return { apply, backupManifestPath };
}

function initAdminFirestore() {
  const saPath = process.env.GOOGLE_APPLICATION_CREDENTIALS;
  const credential = saPath && fs.existsSync(saPath)
    ? cert(JSON.parse(fs.readFileSync(saPath, 'utf-8')))
    : applicationDefault();

  const app = initializeApp({
    credential,
    projectId: process.env.FIREBASE_PROJECT_ID || DEFAULT_PROJECT_ID,
  });

  const databaseId = process.env.FIRESTORE_DATABASE_ID?.trim() || '';
  return databaseId ? getFirestore(app, databaseId) : getFirestore(app);
}

async function runMigration() {
  const { apply, backupManifestPath } = parseArgs();

  if (apply) {
    if (!backupManifestPath || !fs.existsSync(backupManifestPath)) {
      console.error(
        '[MIGRATION] ABORTED: --apply requires a valid --backup-manifest <path> created by backupFirestore.ts.'
      );
      process.exit(1);
    }
    const manifest = JSON.parse(fs.readFileSync(backupManifestPath, 'utf-8'));
    if (!manifest.createdAt || !manifest.counts) {
      console.error('[MIGRATION] ABORTED: Backup manifest is invalid or incomplete.');
      process.exit(1);
    }
    console.log(`[MIGRATION] Verified backup manifest from ${manifest.createdAt}`);
  } else {
    console.log('[MIGRATION] Running in DRY-RUN mode (no writes will be performed).');
  }

  const db = initAdminFirestore();
  const nowIso = new Date().toISOString();

  const companiesSnap = await db.collection('companies').get();
  const existingCompanies: RawDocument[] = companiesSnap.docs.map(d => ({ id: d.id, data: d.data() }));

  const collections: Record<string, RawDocument[]> = {};
  for (const colName of COMPANY_OWNED_COLLECTIONS) {
    const snap = await db.collection(colName).get();
    collections[colName] = snap.docs.map(d => ({ id: d.id, data: d.data() }));
  }

  const taskComments: { taskId: string; comment: RawDocument }[] = [];
  for (const taskDoc of collections.tasks || []) {
    const commentsSnap = await db.collection('tasks').doc(taskDoc.id).collection('comments').get();
    for (const cDoc of commentsSnap.docs) {
      taskComments.push({
        taskId: taskDoc.id,
        comment: { id: cDoc.id, data: cDoc.data() },
      });
    }
  }

  const { items, summary } = buildFullMigrationPlan({
    existingCompanies,
    collections,
    taskComments,
    nowIso,
  });

  console.log('\n[MIGRATION] Planned Summary:');
  console.log(JSON.stringify(summary, null, 2));

  if (!apply) {
    console.log('\n[MIGRATION] Dry-run complete. Pass --apply --backup-manifest <path> to execute.');
    return;
  }

  const writes = items.filter(i => i.operation === 'create' || i.operation === 'merge');
  const BATCH_SIZE = 400;
  let committed = 0;

  for (let i = 0; i < writes.length; i += BATCH_SIZE) {
    const chunk = writes.slice(i, i + BATCH_SIZE);
    const batch = db.batch();

    for (const item of chunk) {
      if (!item.payload) continue;
      const docRef = db.doc(`${item.collection}/${item.docId}`);
      if (item.operation === 'create') {
        batch.set(docRef, item.payload);
      } else {
        batch.set(docRef, item.payload, { merge: true });
      }
    }

    await batch.commit();
    committed += chunk.length;
    console.log(`[MIGRATION] Committed ${committed}/${writes.length} document writes...`);
  }

  console.log('\n[MIGRATION] Migration finished cleanly. Run verifyMigration.ts next.');
}

runMigration().catch(err => {
  console.error('[MIGRATION] Failed:', err);
  process.exit(1);
});
